//! xyd_opensdk_dotnet — Rust port of the IR→C# emission from
//! `@xyd-js/opensdk-dotnet` (System.Net.Http + System.Text.Json).
//!
//! SCOPE (byte-exact against the golden `output/` tree): the FULL generated file
//! tree — `<Sdk>.csproj`, `Client.cs`, `Models.cs`, one `<Resource>Service.cs`
//! per top-level resource, the vendored runtime (`Transport.cs`, and
//! `Pagination.cs` when some method paginates), and the SDK's own dependency-free
//! test project `<Sdk>.Tests/**`. Faithful to the framework orchestrator
//! capability order (project → client → types → resources → runtime → tests);
//! the `// <auto-generated>` machine-ownership header is baked into each `.cs`
//! file (and the `<!-- ... -->` variant into each `.csproj`) by the writers.

mod behavior;
mod cli;
mod client;
mod cstype;
mod cswriter;
mod example_cs;
mod example_plan;
