use std::collections::BTreeMap;

use serde_json::Value;

use client::{render_client_file, DotnetClientCtx};
use cswriter::{escape_xml, CSPROJ_HEADER};
use jsrt::pascal_case;
use model::render_models_file;
use plan::plan_operation;
use runtime::{render_pagination_file, render_transport_file, DotnetRuntimeCtx};
use service::{render_service_file, Behavior, DotnetServiceCtx};
use tests_gen::{render_test_files, DotnetTestsCtx};

pub(crate) struct ResolvedOptions {
    pub(crate) sdk: String,
    pub(crate) namespace: String,
    pub(crate) base_url: String,
    pub(crate) target_framework: String,
    pub(crate) env_var: Option<String>,
}

pub(crate) fn resolve_options(spec: &Value) -> ResolvedOptions {
    let title = spec
        .get("info")
        .and_then(|i| i.get("title"))
        .and_then(Value::as_str)
        .unwrap_or("");
    let sdk = {
        let p = pascal_case(title);
        if p.is_empty() {
            "Client".to_string()
        } else {
            p
        }
    };
    let namespace = format!("Example.{sdk}");
    let base_url = spec
        .get("servers")
        .and_then(Value::as_array)
        .and_then(|s| s.first())
        .and_then(Value::as_str)
        .unwrap_or("")
        .to_string();
    let env_var = spec
        .get("security")
        .and_then(Value::as_array)
        .and_then(|arr| {
            arr.iter()
                .find_map(|s| s.get("envVar").and_then(Value::as_str))
        })
        .map(str::to_string);
    ResolvedOptions {
        sdk,
        namespace,
        base_url,
        target_framework: "net8.0".to_string(),
        env_var,
    }
}

/// Resolve the idempotency policy `service.ts` reads (defaults: autoGenerateForPost=true, maxRetries=2).
fn resolve_behavior(spec: &Value) -> Behavior {
    let sdk = spec.get("sdk");
    let auto_generate_for_post = sdk
        .and_then(|s| s.get("idempotency"))
        .and_then(|i| i.get("autoGenerateForPost"))
        .and_then(Value::as_bool)
        .unwrap_or(true);
    let max_retries = sdk
        .and_then(|s| s.get("retry"))
        .and_then(|r| r.get("maxRetries"))
        .and_then(Value::as_i64)
        .unwrap_or(2);
    Behavior {
        auto_generate_for_post,
        max_retries,
    }
}

/// XML-escaped `.csproj` string with NuGet packaging metadata from `spec.info`.
/// `tests_exclusion` adds the `<Compile Remove="{sdk}.Tests/**">` ItemGroup that
/// keeps the nested test project out of the SDK assembly — HTTP mode only (CLI
/// mode generates no test project).
pub(crate) fn csproj_file(
    sdk: &str,
    namespace_name: &str,
    target_framework: &str,
    spec: &Value,
    tests_exclusion: bool,
) -> String {
    let info = spec.get("info").cloned().unwrap_or(Value::Null);
    let get_str = |path: &[&str]| -> Option<String> {
        let mut cur = &info;
        for p in path {
            cur = cur.get(*p)?;
        }
        cur.as_str().filter(|s| !s.is_empty()).map(str::to_string)
    };
    let version = get_str(&["version"]).unwrap_or_else(|| "0.0.0".to_string());
    // `major.0.0.0` — the stable assembly-version policy. Assembly-version
    // parts are UInt16, so deriving them from <Version> breaks for large
    // segments (a `0.0.<timestamp>` release scheme fails pack with CS7034).
    let assembly_version = {
        let digits: String = version.chars().take_while(|c| c.is_ascii_digit()).collect();
        let major: u64 = if digits.is_empty() {
            0
        } else {
            digits.parse::<u64>().map(|v| v.min(65535)).unwrap_or(65535)
        };
        format!("{major}.0.0.0")
    };
    let mut pkg: Vec<String> = vec![
        "    <IsPackable>true</IsPackable>".to_string(),
        format!("    <PackageId>{}</PackageId>", escape_xml(sdk)),
        format!("    <Version>{}</Version>", escape_xml(&version)),
        format!("    <AssemblyVersion>{assembly_version}</AssemblyVersion>"),
        format!("    <FileVersion>{assembly_version}</FileVersion>"),
    ];
    if let Some(name) = get_str(&["contact", "name"]) {
        pkg.push(format!("    <Authors>{}</Authors>", escape_xml(&name)));
    }
    if let Some(desc) = get_str(&["description"]) {
        pkg.push(format!(
            "    <Description>{}</Description>",
            escape_xml(&desc)
        ));
    }
    if let Some(lic) = get_str(&["license", "identifier"]) {
        pkg.push(format!(
            "    <PackageLicenseExpression>{}</PackageLicenseExpression>",
            escape_xml(&lic)
        ));
    }
    if let Some(repo) = get_str(&["repository"]) {
        pkg.push(format!(
            "    <RepositoryUrl>{}</RepositoryUrl>",
            escape_xml(&repo)
        ));
    }
    if let Some(home) = get_str(&["homepage"]) {
        pkg.push(format!(
            "    <PackageProjectUrl>{}</PackageProjectUrl>",
            escape_xml(&home)
        ));
    }
    let item_group = if tests_exclusion {
        format!(
            "\n  <ItemGroup>\n    <!-- The generated test project lives in a nested {sdk}.Tests/ folder; keep\n         its sources (and its build output's obj/ AssemblyInfo) out of THIS\n         assembly. Otherwise the SDK-style default **/*.cs glob would compile them\n         too, double-declaring assembly attributes once the test project has built\n         (CS0579) and pulling the test framework's types into the SDK (CS0436). -->\n    <Compile Remove=\"{sdk}.Tests/**/*.cs\" />\n  </ItemGroup>\n"
        )
    } else {
        String::new()
    };
    format!(
        "{CSPROJ_HEADER}\n<Project Sdk=\"Microsoft.NET.Sdk\">\n\n  <PropertyGroup>\n    <TargetFramework>{target_framework}</TargetFramework>\n    <LangVersion>latest</LangVersion>\n    <Nullable>enable</Nullable>\n    <ImplicitUsings>disable</ImplicitUsings>\n    <RootNamespace>{namespace_name}</RootNamespace>\n    <AssemblyName>{sdk}</AssemblyName>\n    <GenerateDocumentationFile>false</GenerateDocumentationFile>\n{}\n  </PropertyGroup>\n{item_group}\n</Project>\n",
        pkg.join("\n")
    )
}

/// Generate the substantive IR→C# files (`.csproj`, `Client.cs`, `Models.cs`,
/// `<Resource>Service.cs`). The vendored runtime + tests are out of scope.
pub fn generate_dotnet(spec: &Value) -> BTreeMap<String, String> {
    if xyd_opensdk_cli_common::is_cli_spec(spec) {
        return cli::generate_cli(spec);
    }
    let opts = resolve_options(spec);

    // Symbol table for lookups (order-independent; iteration uses the array).
    let types_arr = spec
        .get("types")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let mut table: BTreeMap<String, Value> = BTreeMap::new();
    for t in &types_arr {
        if let Some(name) = t.get("name").and_then(Value::as_str) {
            table.insert(name.to_string(), t.clone());
        }
    }

    let mut files: BTreeMap<String, String> = BTreeMap::new();

    // generateProject → <Sdk>.csproj
    files.insert(
        format!("{}.csproj", opts.sdk),
        csproj_file(
            &opts.sdk,
            &opts.namespace,
            &opts.target_framework,
            spec,
            true,
        ),
    );

    // generateClient → Client.cs
    files.insert(
        "Client.cs".to_string(),
        render_client_file(
            spec,
            &DotnetClientCtx {
                sdk: &opts.sdk,
                namespace: &opts.namespace,
                base_url: &opts.base_url,
                env_var: opts.env_var.as_deref(),
            },
        ),
    );

    // generateTypes → Models.cs (always emitted, even for an empty symbol table)
    files.insert(
        "Models.cs".to_string(),
        render_models_file(&types_arr, &opts.namespace, &table),
    );

    // generateResources → one <Resource>Service.cs per top-level resource
    let resources = spec
        .get("resources")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let svc_ctx = DotnetServiceCtx {
        namespace: &opts.namespace,
        types: &table,
        behavior: resolve_behavior(spec),
    };
    for r in &resources {
        let (path, content) = render_service_file(r, &svc_ctx);
        files.insert(path, content);
    }

    // generateRuntime → Transport.cs (+ Pagination.cs when some method paginates,
    // so there is no dead runtime code).
    let rt_ctx = DotnetRuntimeCtx {
        sdk: &opts.sdk,
        namespace: &opts.namespace,
        base_url: &opts.base_url,
    };
    files.insert(
        "Transport.cs".to_string(),
        render_transport_file(spec, &rt_ctx),
    );
    if resources.iter().any(|r| resource_paginates(r, &table)) {
        files.insert(
            "Pagination.cs".to_string(),
            render_pagination_file(&opts.namespace),
        );
    }

    // generateTests → <Sdk>.Tests/** (skipped when there are no resources, matching
    // the JS emitter's `resources.length === 0` guard).
    if !resources.is_empty() {
        let tests_ctx = DotnetTestsCtx {
            sdk: &opts.sdk,
            namespace: &opts.namespace,
            target_framework: &opts.target_framework,
            types: &table,
        };
        for (path, content) in render_test_files(&resources, &tests_ctx) {
            files.insert(path, content);
        }
    }

    files
}

/// Whether any method in a resource subtree returns a page — the `Pagination.cs`
/// gate (mirrors `walkMethods(spec).some(dotnetPageName(...) !== null)`).
fn resource_paginates(resource: &Value, types: &BTreeMap<String, Value>) -> bool {
    resource
        .get("methods")
        .and_then(Value::as_array)
        .map(|ms| {
            ms.iter()
                .any(|m| plan_operation(m, types).page_name.is_some())
        })
        .unwrap_or(false)
        || resource
            .get("resources")
            .and_then(Value::as_array)
            .map(|rs| rs.iter().any(|sub| resource_paginates(sub, types)))
            .unwrap_or(false)
}
